import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"泰","description":"周易集解 - 泰","frontmatter":{"title":"泰","description":"周易集解 - 泰"},"headers":[],"relativePath":"zh/classics/jijie/011.md","filePath":"zh/classics/jijie/011.md"}'),l={name:"zh/classics/jijie/011.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="泰" tabindex="-1">泰 <a class="header-anchor" href="#泰" aria-label="Permalink to “泰”">​</a></h1><h2 id="泰-1" tabindex="-1">泰 <a class="header-anchor" href="#泰-1" aria-label="Permalink to “泰”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>泰，小往大來，吉，亨。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《序卦》曰：履而泰，然後安，故受之以泰。泰者，通也。</p><p>崔憬曰：以禮導之必通，通然後安，所謂君子以辯上下，定民志，通而安也。</p><p>虞翻曰：陽息坤反，否也。坤陰詘外，為小往。乾陽信內，稱大來。天地交，萬物通，故吉亨。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：泰，小往大來，吉，亨。則是天地交而萬物通也；上下交而其志同也；內陽而外陰，內健而外順；內君子而外小人，君子道長，小人道消也。</p><h2 id="彖传注" tabindex="-1">彖传注 <a class="header-anchor" href="#彖传注" aria-label="Permalink to “彖传注”">​</a></h2><p>蜀才曰：此本坤卦。小，謂陰也。大，謂陽也。天氣下，地氣上，陰陽交，萬物通，故吉亨。</p><p>何妥曰：此明天道泰也。夫泰之為道，本以通生萬物。若天氣上騰，地氣下降，各自閉塞，不能相交，則萬物無由得生。明萬物生，由天地交也。</p><p>何妥曰：此明人事泰也。上之與下，猶君之與臣，君臣相交感，乃可以濟養民也。天地以氣通，君臣以志同也。</p><p>何妥曰：此明天道也。陰陽之名，就爻為語。健順之稱，指卦為言。順而陰居外，故曰小往。健而陽在內，故曰大來。</p><p>崔憬曰：此明人事也。陽為君子，在內，健於行事。陰為小人，在外，順以聽命。</p><p>《九家易》曰：謂陽息而升，陰消而降也。陽稱息者，長也。起複成巽，萬物盛長也。陰言消者，起姤終乾。萬物成熟。成熟則給用，給用則分散。故陰用特言消也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：天地交泰，後以財成天地之道，輔相天地之宜，以左右民。</p><h2 id="象传注" tabindex="-1">象传注 <a class="header-anchor" href="#象传注" aria-label="Permalink to “象传注”">​</a></h2><p>荀爽曰：坤氣上升，以成天道。乾氣下降，以成地道。天地二氣，若時不交，則為閉塞。今既相交，乃通泰。</p><p>虞翻曰：後，君也。陰升乾位。坤，女主，故稱後。坤富，稱財。守位以人，聚人以財，故曰成天地之道。</p><p>虞翻曰：相，贊。左右，助之。震為左，兌為右，坤為民，謂以陰輔陽。《詩》曰：宜民宜人，受祿於天。</p><p>鄭玄曰：財，節也。輔，相。左右，助也。以者，取其順陰陽之節，為出內之政。春崇寬仁，夏以長養，秋教收斂，冬敕蓋藏，皆可以成物助民也。</p><h2 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h2><p>初九，拔茅茹，以其彙，徵吉。</p><h2 id="初九注" tabindex="-1">初九注 <a class="header-anchor" href="#初九注" aria-label="Permalink to “初九注”">​</a></h2><p>王弼曰：茅之為物，拔其根而相牽引也。茹，相牽引之貌也。三陽同志，俱志在外。初為類首，己舉則從，若茅茹也。上順而應，不為違距，進皆得志。故「以其類，徵吉」也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：拔茅徵吉，志在外也。</p><h2 id="象传注-1" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-1" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：否泰反其類，否巽為茅。茹，茅根。艮為手。彙，類也。初應四，故拔茅茹以彙。震為徵，得位應四，徵吉。志在外，外謂四也。</p><h2 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h2><p>九二，包荒，用馮河，不遐遺。朋亡，得尚於中行。</p><h2 id="九二注" tabindex="-1">九二注 <a class="header-anchor" href="#九二注" aria-label="Permalink to “九二注”">​</a></h2><p>翟玄曰：荒，虛也。二五相應，五虛無陽，二上包之。</p><p>荀爽曰：河出於乾，行於地中。陽性欲升，陰性欲承。馮河而上，不用舟航。自地升天，道雖遼遠，三體俱上，不能止之，故曰不遐遺。</p><p>荀爽曰：中，謂五。坤謂朋，朋亡而下，則二得上居五，而行中和矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：包荒，得尚於中行，以光大也。</p><h2 id="象传注-2" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-2" aria-label="Permalink to “象传注”">​</a></h2><p>虞翻曰：在中稱包。荒，大川也。馮河，涉河。遐，遠；遺，亡也。失位變得正，體坎，坎為大川，為河。震為足。故用馮河。乾為遠，故不遐遺。兌為朋，坤虛無君，欲使二上，故朋亡。二與五易位，故得上於中行。震為行，故光大也。</p><h2 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h2><p>九三，無平不陂，無往不復。艱貞無咎。勿恤其孚，於食有福。</p><h2 id="九三注" tabindex="-1">九三注 <a class="header-anchor" href="#九三注" aria-label="Permalink to “九三注”">​</a></h2><p>虞翻曰：陂，傾。謂否上也。平，謂三。天地分，故平。天成地平，謂危者使［平，易者使］傾。往，謂消外。復，謂息內。從三至上，體復象。終日乾乾，反覆道。故「無平不陂，無往不復」。</p><p>虞翻曰：艱，險。貞，正。恤，憂。孚，信也。二之五得正，在坎中，故艱貞。坎為憂。故勿恤。陽在五孚，險坎為孚，故有孚。體噬嗑，食也。二上之五據四，則三乘二。故於食有福也。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：無平不陂，天地際也。</p><h2 id="象传注-3" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-3" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：位在乾極，應在坤極，天地之際也。地平極則險陂，天行極則還復，故曰「無平不陂，無往不復」也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，翩翩，不富以其鄰，不戒以孚。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：二五變時，四體離飛，故翩翩。坤虛無陽，故不富。兌西震東，故稱其鄰。三陰乘陽，不得之應。《象》曰：「皆失實也。」</p><p>虞翻曰：謂坤。邑人不戒，故使二升五，信來孚邑，故不戒以孚。二上體坎中正。《象》曰：「中心愿也。」與比邑人不戒同義也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：翩翩不富，皆失實也。不戒以孚，中心愿也。</p><h2 id="象传注-4" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-4" aria-label="Permalink to “象传注”">​</a></h2><p>宋衷曰：四互體震，翩翩之象也。陰虛陽實，坤今居上，故言失實也。</p><p>《九家易》曰：乾升坤降，各得其正。陰得承陽，皆陰心之所願也。</p><h2 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h2><p>六五，帝乙歸妹，以祉元吉。</p><h2 id="六五注" tabindex="-1">六五注 <a class="header-anchor" href="#六五注" aria-label="Permalink to “六五注”">​</a></h2><p>《九家易》曰：五者，帝位，震象稱乙，是為帝乙。六五以陰處尊位，帝者之姊妹。五在震後，明其為妹也。五應於二，當下嫁二。婦人謂嫁曰歸，故言帝乙歸妹。謂下居二，以中和相承，故元吉也。</p><p>虞翻曰：震為帝，坤為乙。帝乙，紂父。歸，嫁也。震為兄，兌妹，故嫁妹。祉，福也。謂五變體離，離為大腹，則妹嫁而孕，得位正中，故以祉元吉也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：以祉元吉，中以行願也。</p><h2 id="象传注-5" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-5" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：五下於二，而得中正，故言中以行願也。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，城復於隍，勿用師，自邑告命，貞吝。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>虞翻曰：否艮為城，故稱城。坤為積土。隍，城下溝，無水稱隍，有水稱池。今泰反否，乾壞為土，艮城不見，而體復象，故城復於隍也。</p><p>虞翻曰：謂二，動時體師。陰皆乘陽，行不順，故勿用師。坤為自邑，震為言，兌為口，否巽為命。今逆陵陽，故自邑告命。命逆不順，陰道先迷，失實遠應，故貞吝。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：城復於隍，其命亂也。</p><h2 id="象传注-6" tabindex="-1">象传注 <a class="header-anchor" href="#象传注-6" aria-label="Permalink to “象传注”">​</a></h2><p>《九家易》曰：乾當來上，不可用師而拒之也。自邑者，謂從坤而降也。告命者，謂下為巽，宣佈君之命令也。三陰自相告語，俱下服順承乾也。城復於隍，國政崩也。坤為亂，否巽為命，交在泰上，故其命亂也。</p>',79)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
